WITH dim_totals AS (SELECT s.device, src.event_type, COUNT(*) AS cnt, ROUND(AVG(src.duration_sec), 2) AS avg_duration_sec FROM web_events src LEFT JOIN sessions s ON src.session_id = s.id GROUP BY GROUPING SETS ((s.device, src.event_type), (s.device), ())) SELECT device, event_type, cnt, avg_duration_sec, CASE WHEN device RLIKE '^(mobile|tablet)$' THEN 'GROUP_A' WHEN device RLIKE '^(desktop)$' THEN 'OTHER_ZONE' ELSE 'PRIORITY' END AS device_zone FROM dim_totals ORDER BY avg_duration_sec DESC, device_zone DESC
